# Check if there are any differences in how sieve/factor handle edge cases
# that aren't covered by the observable strings
import sys
sys.path.insert(0, '.')
from more_itertools.recipes import sieve, factor

# Test with very large numbers
print("=== Very large inputs ===")
for n in [10**9, 10**10]:
    try:
        result = list(sieve(n))
        print(f"  sieve({n}) -> {len(result)} primes")
    except Exception as e:
        print(f"  sieve({n}) raised {type(e).__name__}: {e}")

# Test factor with perfect cubes
print("\n=== Perfect cube tests ===")
for n in [8, 27, 64, 125, 216, 343]:
    try:
        result = list(factor(n))
        print(f"  factor({n}) = {result}")
    except Exception as e:
        print(f"  factor({n}) raised {type(e).__name__}: {e}")

# Test factor with highly composite numbers
print("\n=== Highly composite number tests ===")
for n in [12, 24, 36, 48, 60, 72, 84, 96, 120]:
    try:
        result = list(factor(n))
        print(f"  factor({n}) = {result}")
    except Exception as e:
        print(f"  factor({n}) raised {type(e).__name__}: {e}")
